"""Four original RGB source cameras for C147311 one-way construction."""
from contextlib import contextmanager

PROFILE = {'overview': (1920, 1080), 'approach': (1280, 720),
           'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms, plan):
    rows = {row['name']: row for row in plan}
    if set(rows) != set(PROFILE) or set(transforms) != set(PROFILE):
        raise ValueError('All four named source cameras required')
    sensors = {}
    try:
        for name, size in PROFILE.items():
            row = rows[name]
            if (row.get('width'), row.get('height')) != size:
                raise ValueError('Pinned source camera dimensions required')
            fov = row.get('fov_deg')
            if type(fov) not in (int, float) or not 30 <= fov <= 120:
                raise ValueError('Source camera FOV required')
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            for key, value in [('image_size_x', size[0]), ('image_size_y', size[1]),
                               ('fov', fov), ('sensor_tick', 0.05)]:
                blueprint.set_attribute(key, str(value))
            kwargs = {'attach_to': ego} if name == 'driver_reference' else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError('Native camera spawn failed: ' + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""CARLA-independent route follower for both directions of the same lane."""
import math


def _finite_pair(values, label):
 if not isinstance(values,(list,tuple)) or len(values)!=2:
  raise ValueError('Invalid '+label)
 if any(type(v) not in (int,float) or not math.isfinite(v) for v in values):
  raise ValueError('Nonfinite '+label)
 return float(values[0]),float(values[1])


class RouteFollower:
 def __init__(self, route_xy_m, *, target_speed_mps=4.0, reach_m=2.0):
  if not isinstance(route_xy_m,list) or len(route_xy_m)<2:
   raise ValueError('Route needs at least two points')
  self.route=[_finite_pair(p,'route point') for p in route_xy_m]
  if target_speed_mps<=0 or not math.isfinite(target_speed_mps):
   raise ValueError('Invalid target speed')
  if reach_m<=0 or not math.isfinite(reach_m):raise ValueError('Invalid waypoint reach')
  if any(math.dist(a,b)<0.1 for a,b in zip(self.route,self.route[1:])):
   raise ValueError('Duplicate route points')
  self.speed=float(target_speed_mps);self.reach=float(reach_m);self.index=1

 def step(self, position_xy_m, forward_xy, speed_mps):
  px,py=_finite_pair(position_xy_m,'position')
  fx,fy=_finite_pair(forward_xy,'forward')
  fn=math.hypot(fx,fy)
  if fn<0.1:raise ValueError('Zero vehicle forward')
  if type(speed_mps) not in (int,float) or not math.isfinite(speed_mps) or speed_mps<0:
   raise ValueError('Invalid observed speed')
  while self.index<len(self.route)-1 and math.dist((px,py),self.route[self.index])<=self.reach:
   self.index+=1
  tx,ty=self.route[self.index];vx,vy=tx-px,ty-py
  distance=math.hypot(vx,vy)
  if distance<=self.reach and self.index==len(self.route)-1:
   return {'throttle':0.0,'brake':1.0,'steer':0.0,'target_index':self.index,
           'route_complete':True,'target_distance_m':distance}
  if distance<0.1:raise ValueError('Route target coincides with vehicle')
  # Signed planar angle is positive for a target to the vehicle's left.
  angle=math.atan2(fx*vy-fy*vx,fx*vx+fy*vy)
  steer=max(-1.0,min(1.0,angle/math.radians(40)))
  error=self.speed-float(speed_mps)
  return {'throttle':max(0.0,min(0.45,0.12*error)),
          'brake':max(0.0,min(0.6,-0.2*error)),
          'steer':steer,'target_index':self.index,'route_complete':False,
          'target_distance_m':distance}

"""Native lane inventory and paired route construction for a one-way comparison.

The authority designation and installed signs must be supplied separately. Native
lane topology alone cannot establish either legal fact.
"""
import math
from pathlib import Path
import importlib.util

def verify_multilane_one_way(world,road_id,lane_ids,*,spacing_m=2.0):
 if len(set(lane_ids))<2:raise ValueError('Two driving lanes required')
 observed={wp.lane_id for wp in world.get_map().generate_waypoints(spacing_m) if wp.road_id==road_id and str(wp.lane_type).lower().endswith('driving')}
 if not set(lane_ids)<=observed:raise ValueError('Selected Native driving lanes missing')
 if any(i>0 for i in lane_ids) and any(i<0 for i in lane_ids):raise ValueError('Selected lanes include opposing Native directions')
 return {'road_id':road_id,'selected_lane_ids':sorted(set(lane_ids)),'designation_and_signpost_status':'source review required'}


def paired_route_points(world, road_id, lane_ids, designated_forward_xy, *,
                        travel_lane_id, min_span_m=12.0, spacing_m=2.0):
 """Return opposing travel routes on the *same* Native driving lane.

 This is a construction plan, not proof that CARLA will realize the wrong-way
 trajectory. Coordinates come from sampled Native waypoints; an operator must
 bind the designation and signs to reviewed site sources before capture.
 """
 verify_multilane_one_way(world, road_id, lane_ids, spacing_m=spacing_m)
 if travel_lane_id not in lane_ids:
  raise ValueError('Travel lane is not in selected one-way lanes')
 if len(designated_forward_xy)!=2 or any(not isinstance(v,(int,float)) or isinstance(v,bool) or not math.isfinite(v) for v in designated_forward_xy):
  raise ValueError('Invalid designated direction')
 dx,dy=map(float,designated_forward_xy)
 norm=math.hypot(dx,dy)
 if norm==0:raise ValueError('Zero designated direction')
 dx,dy=dx/norm,dy/norm
 waypoints=[wp for wp in world.get_map().generate_waypoints(spacing_m)
            if wp.road_id==road_id and wp.lane_id==travel_lane_id
            and str(wp.lane_type).lower().endswith('driving')]
 if len(waypoints)<2:raise ValueError('Insufficient Native route waypoints')
 points=[]
 for wp in waypoints:
  location=wp.transform.location
  x,y=float(location.x),float(location.y)
  if not math.isfinite(x) or not math.isfinite(y):raise ValueError('Nonfinite Native waypoint')
  points.append((x*dx+y*dy,x,y))
 points.sort()
 if points[-1][0]-points[0][0]<min_span_m:
  raise ValueError('Native route span too short')
 # Collapse duplicated projections, which can arise at junction waypoint samples.
 route=[]
 for progress,x,y in points:
  if not route or progress-route[-1][0]>0.1:route.append((progress,x,y))
 if len(route)<2:raise ValueError('Native route has no distinct progression')
 forward=[[x,y] for _,x,y in route]
 return {'road_id':road_id,'lane_id':travel_lane_id,
         'designated_forward_xy':[dx,dy],
         'with_designation_xy_m':forward,
         'against_designation_xy_m':list(reversed(forward)),
         'span_m':route[-1][0]-route[0][0],
         'designation_and_signpost_status':'source review required'}


def prepare_reviewed_route(world, packet, source_root, *, travel_lane_id, min_span_m=12.0):
 """Join hashed site sources to the exact Native lane route before capture."""
 spec=importlib.util.spec_from_file_location('one_way_site_review',Path(__file__).with_name('site_review.py'))
 module=importlib.util.module_from_spec(spec)
 spec.loader.exec_module(module)
 map_id=world.get_map().name
 review=module.validate(packet,source_root,expected_map_id=map_id,
                             road_id=packet['road_id'],lane_ids=packet['driving_lane_ids'])
 route=paired_route_points(world,packet['road_id'],packet['driving_lane_ids'],
                           packet['designated_forward_xy'],
                           travel_lane_id=travel_lane_id,min_span_m=min_span_m)
 return {'site_review':review,'routes':route}

"""Validate source bindings for a proposed signposted one-way site.

This checks completeness and byte identity only. Whether the cited designation
has legal force and whether a sign governs the route require independent review.
"""
import hashlib
import math
from pathlib import Path


def _source(root, row, label):
 if not isinstance(row,dict) or not row.get('path') or not row.get('sha256'):
  raise ValueError('Missing '+label+' source binding')
 rel=Path(row['path'])
 if rel.is_absolute() or '..' in rel.parts:
  raise ValueError('Unsafe '+label+' source path')
 path=Path(root)/rel
 if not path.is_file():raise ValueError('Missing '+label+' source file')
 digest=hashlib.sha256(path.read_bytes()).hexdigest()
 if digest!=row['sha256']:raise ValueError('Stale '+label+' source hash')
 return {'path':str(rel),'sha256':digest}


def validate(packet, source_root, *, expected_map_id, road_id, lane_ids):
 if not isinstance(packet,dict):raise ValueError('Site packet must be an object')
 if packet.get('native_map_id')!=expected_map_id or packet.get('road_id')!=road_id:
  raise ValueError('Site packet Native road identity differs')
 if set(packet.get('driving_lane_ids',[]))!=set(lane_ids) or len(set(lane_ids))<2:
  raise ValueError('Site packet selected lanes differ')
 if not packet.get('highway_id') or not packet.get('designation_text'):
  raise ValueError('Designation identity and exact text required')
 direction=packet.get('designated_forward_xy')
 if not isinstance(direction,list) or len(direction)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in direction) or math.hypot(*direction)<0.5:
  raise ValueError('Designated direction invalid')
 if not packet.get('reviewer') or not packet.get('designation_review_basis'):
  raise ValueError('Independent designation review basis required')
 designation=_source(source_root,packet.get('designation_source'),'designation')
 signs=packet.get('signs')
 if not isinstance(signs,list) or not signs:
  raise ValueError('One-way sign inventory required')
 seen=set();bound=[]
 for sign in signs:
  if not isinstance(sign,dict) or not sign.get('sign_id') or sign['sign_id'] in seen:
   raise ValueError('Distinct sign identity required')
  seen.add(sign['sign_id'])
  if sign.get('code')!='one_way' or sign.get('governs_road_id')!=road_id:
   raise ValueError('Sign must be one-way and govern selected road')
  if not set(lane_ids)<=set(sign.get('governs_lane_ids',[])):
   raise ValueError('Sign coverage omits selected lane')
  location=sign.get('location_xy_m')
  if not isinstance(location,list) or len(location)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in location):
   raise ValueError('Sign location invalid')
  bound.append({'sign_id':sign['sign_id'],'source':_source(source_root,sign.get('source'),'sign')})
 return {'format':'worker-one-way-site-source-check',
         'native_map_id':expected_map_id,'highway_id':packet['highway_id'],
         'road_id':road_id,'selected_lane_ids':sorted(set(lane_ids)),
         'designation_source':designation,'sign_sources':bound,
         'legal_designation_status':'independent review required',
         'physical_sign_visibility':'unverified'}

"""Source-joined travel direction on a signposted multilane one-way highway."""
import hashlib,importlib.util,json,math
from pathlib import Path
from shapely.geometry import MultiPoint,Polygon
REQUIRED=('road_context.json','site_packet.json','travel_history.jsonl','video_frames.jsonl')
def _finite(x,label):
 if isinstance(x,bool) or not isinstance(x,(float,int)) or not math.isfinite(x):raise ValueError('Missing finite '+label)
 return float(x)
def _rows(path):return [json.loads(s) for s in path.read_text().splitlines() if s.strip()]
def analyze(root:Path)->dict:
 root=Path(root);hashes={}
 for name in REQUIRED:
  p=root/name
  if not p.is_file():raise ValueError('Missing original source: '+name)
  hashes[name]=hashlib.sha256(p.read_bytes()).hexdigest()
 ctx=json.loads((root/'road_context.json').read_text())
 for key in ('native_map_id','highway_id','road_id','one_way_designation_source','direction_sign_source','lane_geometry_source','travel_route_source'):
  if not ctx.get(key):raise ValueError('Missing road context: '+key)
 lanes=ctx.get('driving_lane_ids')
 if not isinstance(lanes,list) or len(set(lanes))<2:raise ValueError('Multilane highway not sourced')
 packet=json.loads((root/'site_packet.json').read_text())
 spec=importlib.util.spec_from_file_location('one_way_saved_site_review',Path(__file__).with_name('site_review.py'))
 site=importlib.util.module_from_spec(spec);spec.loader.exec_module(site)
 review=site.validate(packet,root,expected_map_id=ctx['native_map_id'],
                      road_id=ctx['road_id'],lane_ids=lanes)
 if review['highway_id']!=ctx['highway_id'] or packet['designated_forward_xy']!=ctx.get('designated_forward_xy'):
  raise ValueError('Saved site packet differs from road context')
 direction=ctx.get('designated_forward_xy')
 if not isinstance(direction,list) or len(direction)!=2:raise ValueError('Designated direction missing')
 dx,dy=(_finite(v,'designated direction') for v in direction);norm=math.hypot(dx,dy)
 if norm==0:raise ValueError('Zero designated direction')
 dx,dy=dx/norm,dy/norm
 polygon=Polygon(ctx.get('one_way_roadway_polygon_xy_m',[]))
 if not polygon.is_valid or polygon.area<=0:raise ValueError('Invalid one-way roadway')
 rows,frames=_rows(root/'travel_history.jsonl'),_rows(root/'video_frames.jsonl')
 if len(rows)<2 or len(rows)!=len(frames):raise ValueError('Incomplete travel history')
 prev=(-1,-math.inf);samples=[];centers=[]
 for i,(row,frame) in enumerate(zip(rows,frames)):
  fid,time=row.get('frame'),_finite(row.get('time_s'),'time')
  if type(fid) is not int or fid<=prev[0] or time<=prev[1]:raise ValueError('Nonmonotone original history')
  prev=fid,time
  if frame.get('video_frame')!=i or frame.get('carla_frame')!=fid or frame.get('time_s')!=time:raise ValueError('Original frame join failed')
  if row.get('road_id')!=ctx['road_id'] or row.get('lane_id') not in lanes:raise ValueError('Ego outside sourced one-way lanes')
  vertices=row.get('ego_body_vertices_xy_m')
  if not isinstance(vertices,list) or len(vertices)<4:raise ValueError('Missing complete body')
  body=MultiPoint([(_finite(p[0],'body x'),_finite(p[1],'body y')) for p in vertices]).convex_hull
  if body.area<=0:raise ValueError('Degenerate body')
  forward=row.get('ego_forward_xy')
  if not isinstance(forward,list) or len(forward)!=2:raise ValueError('Ego heading missing')
  fx,fy=(_finite(v,'ego heading') for v in forward);fn=math.hypot(fx,fy)
  if fn==0:raise ValueError('Zero ego heading')
  samples.append({'frame':fid,'time_s':time,'lane_id':row['lane_id'],'complete_body_on_one_way_roadway':polygon.covers(body),'heading_alignment':(fx*dx+fy*dy)/fn})
  centers.append((body.centroid.x,body.centroid.y))
 projected=[(centers[i+1][0]-centers[i][0])*dx+(centers[i+1][1]-centers[i][1])*dy for i in range(len(centers)-1)]
 for bound in [review['designation_source'],*(item['source'] for item in review['sign_sources'])]:
  hashes[bound['path']]=bound['sha256']
 return {'format':'worker-one-way-direction-observations','sources':hashes,
         'site_source_review':review,'samples':samples,'projected_step_m':projected,
         'all_steps_designated_direction':all(v>0 for v in projected),
         'legal_conclusion':'unresolved pending independent designation and physical review'}

